const e=[{number:1,type:"question",question:"ข้อใดคือคำอธิบายของ 'แรงดึงจากการมุดตัว' (Slab Pull) ที่ถูกต้องที่สุด",options:["แรงที่เกิดจากการยกตัวของสันเขาแล้วแผ่นธรณีไถลลง","แรงเสียดทานระหว่างแผ่นธรณีที่เคลื่อนที่ผ่านกัน","แรงโน้มถ่วงที่กระทำต่อแผ่นธรณีส่วนที่มุดตัวและเย็นลง","แรงดันของแมกมาที่พยายามแทรกตัวขึ้นมาที่รอยแยก"],answer:"แรงโน้มถ่วงที่กระทำต่อแผ่นธรณีส่วนที่มุดตัวและเย็นลง",explanation:"Slab Pull คือแรงที่เกิดจากแผ่นธรณีมหาสมุทรส่วนที่มุดตัวลงไปในชั้นเนื้อโลก ซึ่งเมื่อเย็นลงจะมีความหนาแน่นสูงกว่าเนื้อโลกโดยรอบ ทำให้แรงโน้มถ่วง 'ดึง' แผ่นธรณีส่วนนั้นให้จมลึกลงไป และลากแผ่นธรณีส่วนที่เหลือให้เคลื่อนที่ตามไปด้วย",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:2,type:"question",question:"การพบกลุ่มหินและโครงสร้างทางธรณีวิทยาที่มีอายุและลักษณะเหมือนกันในเทือกเขาแอปพาเลเชียน (ทวีปอเมริกาเหนือ) และเทือกเขาคาเลโดเนียน (ทวีปยุโรป) เป็นหลักฐานสนับสนุนทฤษฎีใด",options:["ทฤษฎีการเกิดโลก","ทฤษฎีการแผ่ขยายพื้นสมุทร","ทฤษฎีทวีปเลื่อน","ทฤษฎีการเกิดภูเขาไฟ"],answer:"ทฤษฎีทวีปเลื่อน",explanation:"การที่แนวเทือกเขาสองแห่งที่ปัจจุบันถูกแยกจากกันโดยมหาสมุทรแอตแลนติก แต่มีลักษณะทางธรณีวิทยาที่ต่อเนื่องกันได้ เป็นหลักฐานสำคัญที่อัลเฟรด เวเกเนอร์ ใช้สนับสนุนแนวคิดที่ว่าทวีปเหล่านี้เคยเชื่อมต่อกันเป็นส่วนหนึ่งของมหาทวีปพันเจีย",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/2 อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี"}},{number:3,type:"question",question:"รอยเลื่อนตามแนวระดับขนาดใหญ่ (Transform Fault) ที่เชื่อมต่อระหว่างส่วนของสันเขากลางสมุทรที่แยกจากกัน มีความสำคัญอย่างไร",options:["เป็นบริเวณที่มีการสร้างเปลือกโลกใหม่ขึ้นมาทดแทน","เป็นบริเวณที่มักเกิดการระเบิดของภูเขาไฟอย่างรุนแรง","เป็นบริเวณที่รองรับการเคลื่อนที่ของแผ่นธรณีที่ไม่เท่ากัน","เป็นบริเวณที่เปลือกโลกเก่าถูกทำลายลงไปในชั้นเนื้อโลก"],answer:"เป็นบริเวณที่รองรับการเคลื่อนที่ของแผ่นธรณีที่ไม่เท่ากัน",explanation:"เนื่องจากโลกเป็นทรงกลม อัตราการแผ่ขยายของพื้นสมุทรในแต่ละส่วนจึงไม่เท่ากัน รอยเลื่อนตามแนวระดับขนาดใหญ่ทำหน้าที่เป็นแนวที่ช่วยให้ส่วนต่างๆ ของแผ่นธรณีที่เคลื่อนที่ด้วยอัตราเร็วต่างกันสามารถเคลื่อนที่ผ่านกันไปได้",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{type:"scenario",title:"สถานการณ์: การวิเคราะห์แผนที่ธรณีแปรสัณฐาน",description:"แผนที่แสดงให้เห็นว่าแผ่นธรณีนาซกา (Nazca Plate) ซึ่งเป็นแผ่นธรณีมหาสมุทรกำลังเคลื่อนที่เข้าหาและมุดตัวลงใต้แผ่นธรณีอเมริกาใต้ (South American Plate) ซึ่งเป็นแผ่นธรณีทวีป",questions:[{number:4,question:"ธรณีสัณฐานที่โดดเด่นซึ่งเป็นผลโดยตรงจากกระบวนการนี้คืออะไร",options:["สันเขากลางมหาสมุทรแอตแลนติกและหุบเขาทรุด","เทือกเขาหิมาลัยและที่ราบสูงทิเบต","ร่องลึกก้นสมุทรเปรู-ชิลี และเทือกเขาแอนดีส","หมู่เกาะภูเขาไฟฮาวายและภูเขาไฟใต้ทะเล"],answer:"ร่องลึกก้นสมุทรเปรู-ชิลี และเทือกเขาแอนดีส",explanation:"การมุดตัวของแผ่นธรณีนาซกาทำให้เกิดร่องลึกก้นสมุทรขนานไปกับชายฝั่ง และการหลอมละลายของแผ่นที่มุดตัวลงไปทำให้เกิดการปะทุของภูเขาไฟ ก่อตัวเป็นแนวเทือกเขาแอนดีสบนแผ่นทวีปอเมริกาใต้",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:5,question:"แผ่นดินไหวที่เกิดขึ้นในบริเวณเทือกเขาแอนดีสจะมีลักษณะอย่างไร",options:["เกิดเฉพาะแผ่นดินไหวระดับตื้นเท่านั้น","เกิดเฉพาะแผ่นดินไหวระดับลึกเท่านั้น","สามารถเกิดแผ่นดินไหวได้ทั้งระดับตื้น กลาง และลึก","ไม่เกิดแผ่นดินไหว แต่เกิดภูเขาไฟรุนแรง"],answer:"สามารถเกิดแผ่นดินไหวได้ทั้งระดับตื้น กลาง และลึก",explanation:"ในเขตมุดตัว แผ่นธรณีที่มุดตัวลงไปจะเสียดสีและแตกหักในระดับความลึกต่างๆ กัน ทำให้เกิดแผ่นดินไหวได้ตั้งแต่ระดับตื้นใกล้ร่องลึก ไปจนถึงระดับลึกหลายร้อยกิโลเมตรใต้แผ่นทวีป",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}}]},{number:6,type:"question",question:"การที่แผ่นธรณีอินเดียยังคงเคลื่อนที่มุดเข้าใต้แผ่นธรณียูเรเชีย ส่งผลให้เทือกเขาหิมาลัยมีการเปลี่ยนแปลงอย่างไรในปัจจุบัน",options:["กำลังทรุดตัวลงอย่างรวดเร็ว","ยังคงสูงขึ้นอย่างต่อเนื่อง","หยุดการเปลี่ยนแปลงแล้ว","กำลังเคลื่อนที่ไปทางทิศตะวันออก"],answer:"ยังคงสูงขึ้นอย่างต่อเนื่อง",explanation:"การชนกันของแผ่นธรณียังคงดำเนินต่อไป ทำให้เทือกเขาหิมาลัยยังคงถูกดันให้สูงขึ้นในอัตราประมาณ 5 มิลลิเมตรต่อปี",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:7,type:"multiple-select",question:"ข้อใดคือหลักฐานที่สนับสนุนทฤษฎีการแผ่ขยายพื้นสมุทร (Seafloor Spreading) (เลือกตอบได้มากกว่า 1 ข้อ)",options:["อายุของหินบะซอลต์ที่พื้นสมุทรเพิ่มขึ้นเมื่อห่างจากสันเขา","ความหนาของชั้นตะกอนบนพื้นสมุทรเพิ่มขึ้นเมื่อห่างจากสันเขา","การพบแถบแม่เหล็กบรรพกาลที่สมมาตรกันบริเวณสันเขา","การพบฟอสซิลพืชชนิดเดียวกันในหลายทวีป"],answer:["อายุของหินบะซอลต์ที่พื้นสมุทรเพิ่มขึ้นเมื่อห่างจากสันเขา","ความหนาของชั้นตะกอนบนพื้นสมุทรเพิ่มขึ้นเมื่อห่างจากสันเขา","การพบแถบแม่เหล็กบรรพกาลที่สมมาตรกันบริเวณสันเขา"],explanation:"หลักฐานทั้งสามข้อแรกล้วนสนับสนุนว่าพื้นสมุทรมีการสร้างใหม่ที่สันเขาและเคลื่อนที่ออกไป ส่วนการพบฟอสซิลเป็นหลักฐานของทฤษฎีทวีปเลื่อน",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/2 อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี"}},{type:"scenario",title:"สถานการณ์: รอยเลื่อนมีพลังในประเทศไทย",description:"นักธรณีวิทยาศึกษาพบว่า ภาคตะวันตกและภาคเหนือของประเทศไทยมีกลุ่มรอยเลื่อนมีพลังขนาดใหญ่หลายแนวพาดผ่านในทิศตะวันตกเฉียงเหนือ-ตะวันออกเฉียงใต้ เช่น รอยเลื่อนแม่ปิง และรอยเลื่อนเจดีย์สามองค์ ซึ่งเป็นสาเหตุของการเกิดแผ่นดินไหวในภูมิภาค",questions:[{number:8,question:"จากข้อมูล รอยเลื่อนเหล่านี้ส่วนใหญ่จัดเป็นรอยเลื่อนประเภทใด",options:["รอยเลื่อนปกติ (Normal Fault)","รอยเลื่อนย้อน (Reverse Fault)","รอยเลื่อนตามแนวระดับ (Strike-slip Fault)","รอยเลื่อนย้อนมุมต่ำ (Thrust Fault)"],answer:"รอยเลื่อนตามแนวระดับ (Strike-slip Fault)",explanation:"รอยเลื่อนมีพลังในประเทศไทยส่วนใหญ่เป็นรอยเลื่อนตามแนวระดับ ซึ่งเกิดจากการเคลื่อนที่ของแผ่นธรณีในแนวราบเป็นหลัก",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:9,question:"การเกิดของกลุ่มรอยเลื่อนเหล่านี้เป็นผลโดยตรงมาจากการแปรสัณฐานของแผ่นธรณีในลักษณะใด",options:["การแยกตัวของแผ่นธรณีฉาน-ไทย","การมุดตัวของแผ่นธรณีแปซิฟิก","การชนกันของแผ่นธรณีอินเดียและยูเรเชีย","การเกิดจุดร้อนใต้ภูมิภาคเอเชียตะวันออกเฉียงใต้"],answer:"การชนกันของแผ่นธรณีอินเดียและยูเรเชีย",explanation:"การชนกันของแผ่นธรณีอินเดียกับยูเรเชียทำให้เกิดแรงเค้นมหาศาล ส่งผลให้แผ่นดินในภูมิภาคเอเชียตะวันออกเฉียงใต้เกิดการเคลื่อนตัวหนีออกไปทางด้านข้าง (Lateral Extrusion) และเกิดเป็นรอยเลื่อนตามแนวระดับขนาดใหญ่หลายแนวในประเทศไทย",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}}]},{number:10,type:"question",question:"การเกิด 'แอ่งโค้งหน้าภูเขาไฟ' (Forearc Basin) สัมพันธ์กับรอยต่อแผ่นธรณีประเภทใด",options:["รอยต่อแบบแยกตัว (Divergent Boundary)","รอยต่อแบบเคลื่อนเข้าหากัน (Subduction Zone)","รอยต่อแบบเคลื่อนผ่านกัน (Transform Boundary)","จุดร้อน (Hotspot)"],answer:"รอยต่อแบบเคลื่อนเข้าหากัน (Subduction Zone)",explanation:"แอ่งโค้งหน้าภูเขาไฟ คือแอ่งตะกอนที่เกิดขึ้นระหว่างร่องลึกก้นสมุทรกับแนวภูเขาไฟรูปโค้ง ซึ่งเป็นลักษณะเฉพาะที่พบในบริเวณเขตมุดตัวของแผ่นธรณี",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:11,type:"question",question:"ข้อใดคือคำอธิบายของ 'แรงผลักจากสันเขา' (Ridge Push) ที่ถูกต้อง",options:["แรงที่แผ่นธรณีที่มุดตัวดึงแผ่นที่เหลือให้ตามลงไป","แรงที่เกิดจากการยกตัวของสันเขาแล้วแผ่นธรณีไถลลงตามความชัน","แรงเสียดทานระหว่างแผ่นธรณีที่เคลื่อนที่ผ่านกัน","แรงจากการพาความร้อนในชั้นเนื้อโลกโดยตรง"],answer:"แรงที่เกิดจากการยกตัวของสันเขาแล้วแผ่นธรณีไถลลงตามความชัน",explanation:"Ridge Push เป็นแรงที่เกิดจากที่สันเขากลางสมุทรยกตัวสูงกว่าพื้นมหาสมุทรโดยรอบ ทำให้เกิดแรงโน้มถ่วงที่ผลักให้แผ่นธรณีเคลื่อนที่ออกจากสันเขา คล้ายกับการไถลลงตามความลาดชัน",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:12,type:"question",question:"การที่แผ่นธรณีมหาสมุทรแปซิฟิกเคลื่อนที่ไปทางตะวันตกเฉียงเหนือ ทำให้เกิดแนวหมู่เกาะฮาวาย-เอมเพอเรอร์ที่มีลักษณะเป็นแนวยาวโค้งงอ การโค้งงอนี้บอกอะไรเราได้",options:["จุดร้อนใต้เปลือกโลกมีการเคลื่อนที่เปลี่ยนตำแหน่งไป","ทิศทางการเคลื่อนที่ของแผ่นธรณีแปซิฟิกมีการเปลี่ยนแปลงในอดีต","ความเร็วในการเคลื่อนที่ของแผ่นธรณีแปซิฟิกไม่คงที่","สนามแม่เหล็กโลกมีการสลับขั้วในช่วงเวลานั้น"],answer:"ทิศทางการเคลื่อนที่ของแผ่นธรณีแปซิฟิกมีการเปลี่ยนแปลงในอดีต",explanation:"แนวการเรียงตัวของภูเขาไฟใต้ทะเลและหมู่เกาะที่เกิดจากจุดร้อนเป็นตัวบันทึกทิศทางการเคลื่อนที่ของแผ่นธรณี การที่แนวหมู่เกาะฮาวาย-เอมเพอเรอร์มีการหักงอ แสดงว่าทิศทางการเคลื่อนที่ของแผ่นธรณีแปซิฟิกได้เปลี่ยนไปเมื่อประมาณ 43 ล้านปีก่อน",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:13,type:"question",question:"ข้อใดคือความแตกต่างระหว่าง 'แผ่นดินไหวระหว่างแผ่น' (Interplate Earthquake) และ 'แผ่นดินไหวภายในแผ่น' (Intraplate Earthquake)",options:["ไม่มีความแตกต่างกันในแง่ของตำแหน่งที่เกิดและสาเหตุการเกิด","แผ่นดินไหวระหว่างแผ่นเกิดตามรอยต่อแผ่นธรณี ส่วนแผ่นดินไหวภายในแผ่นเกิดบนรอยเลื่อนที่อยู่ห่างจากรอยต่อ","แผ่นดินไหวภายในแผ่นมีความรุนแรงและสร้างความเสียหายมากกว่าแผ่นดินไหวระหว่างแผ่นเสมอ","แผ่นดินไหวระหว่างแผ่นมักจะไม่ทำให้เกิดคลื่นสึนามิในมหาสมุทรเหมือนแผ่นดินไหวภายในแผ่น"],answer:"แผ่นดินไหวระหว่างแผ่นเกิดตามรอยต่อแผ่นธรณี ส่วนแผ่นดินไหวภายในแผ่นเกิดบนรอยเลื่อนที่อยู่ห่างจากรอยต่อ",explanation:"แผ่นดินไหวส่วนใหญ่ (Interplate) เกิดขึ้นตามแนวรอยต่อของแผ่นธรณี แต่ก็มีแผ่นดินไหวบางส่วน (Intraplate) ที่สามารถเกิดขึ้นบนรอยเลื่อนเก่าที่อยู่ภายในแผ่นธรณีได้เช่นกัน ซึ่งเกิดจากความเค้นที่สะสมและถ่ายทอดเข้ามาในแผ่นธรณี",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:14,type:"question",question:"การเกิด 'แอ่งโค้งหลังภูเขาไฟ' (Back-arc Basin) มีความสัมพันธ์กับกระบวนการใด",options:["การแยกตัวของแผ่นธรณีทวีปออกจากกันอย่างสมบูรณ์","การมุดตัวของแผ่นธรณีมหาสมุทรที่ทำให้เกิดการยืดขยายตัวด้านหลังแนวภูเขาไฟ","การชนกันของแผ่นธรณีทวีปสองแผ่นจนเกิดเทือกเขาสูง","การเคลื่อนที่ผ่านกันของแผ่นธรณีในแนวระดับโดยไม่มีการสร้างหรือทำลาย"],answer:"การมุดตัวของแผ่นธรณีมหาสมุทรที่ทำให้เกิดการยืดขยายตัวด้านหลังแนวภูเขาไฟ",explanation:"ในบางเขตมุดตัว กระบวนการมุดตัวสามารถเหนี่ยวนำให้เกิดการยืดขยายของเปลือกโลกที่อยู่ด้านหลังแนวภูเขาไฟรูปโค้ง ทำให้เกิดเป็นแอ่งหรือทะเลชายขอบ เช่น ทะเลญี่ปุ่น",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:15,type:"question",question:"ข้อใดคือสาเหตุที่ทำให้เกิด 'วงแหวนแห่งไฟ' (Ring of Fire) รอบมหาสมุทรแปซิฟิก",options:["เป็นแนวของสันเขากลางสมุทร (Mid-Ocean Ridge) ที่ล้อมรอบมหาสมุทร","เป็นแนวของเขตมุดตัว (Subduction Zone) ที่แผ่นธรณีแปซิฟิกล้อมรอบไปด้วย","เป็นแนวของจุดร้อน (Hotspot) ที่เรียงตัวกันเป็นวงกลม","เป็นแนวของรอยเลื่อนตามแนวระดับขนาดใหญ่ (Transform Fault)"],answer:"เป็นแนวของเขตมุดตัว (Subduction Zone) ที่แผ่นธรณีแปซิฟิกล้อมรอบไปด้วย",explanation:"วงแหวนแห่งไฟคือแนวของภูเขาไฟและแผ่นดินไหวที่เกิดขึ้นอย่างหนาแน่นรอบมหาสมุทรแปซิฟิก ซึ่งเป็นผลมาจากการที่แผ่นธรณีแปซิฟิกและแผ่นธรณีขนาดเล็กอื่นๆ กำลังมุดตัวลงใต้แผ่นธรณีทวีปและแผ่นธรณีมหาสมุทรที่อยู่โดยรอบ",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:16,type:"fill-in-number",question:"ถ้าแผ่นธรณีแปซิฟิกเคลื่อนที่ด้วยอัตราเร็ว 8 เซนติเมตรต่อปี จะต้องใช้เวลากี่ล้านปีในการเคลื่อนที่เป็นระยะทาง 400 กิโลเมตร",answer:5,unit:"ล้านปี",hint:"เปลี่ยนหน่วยระยะทางให้เป็นเซนติเมตรก่อน แล้วจึงหารด้วยอัตราเร็วเพื่อหาเวลา",explanation:"ระยะทาง 400 km = 40,000,000 cm. เวลา = ระยะทาง / อัตราเร็ว = 40,000,000 cm / 8 cm/ปี = 5,000,000 ปี หรือ 5 ล้านปี",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:17,type:"question",question:"การพบหินโอฟิโอไลต์ (Ophiolite) ซึ่งเป็นลำดับชั้นหินของเปลือกโลกมหาสมุทรบนแผ่นดินทวีป เป็นหลักฐานของกระบวนการใด",options:["การยกตัวของพื้นมหาสมุทรเนื่องจากการเปลี่ยนแปลงของเปลือกโลก","การชนกันของทวีปที่ทำให้ชิ้นส่วนของเปลือกโลกมหาสมุทรถูกดันขึ้นมา","การเกิดภูเขาไฟใต้ทะเลที่ดันตัวขึ้นมาเหนือผิวน้ำ","การเปลี่ยนแปลงระดับน้ำทะเลที่ลดลงจนเห็นพื้นมหาสมุทร"],answer:"การชนกันของทวีปที่ทำให้ชิ้นส่วนของเปลือกโลกมหาสมุทรถูกดันขึ้นมา",explanation:"โอฟิโอไลต์คือเศษเสี้ยวของเปลือกโลกมหาสมุทรและเนื้อโลกส่วนบนสุดที่ถูกดันขึ้นมาบนแผ่นทวีปในระหว่างกระบวนการเกิดเทือกเขาจากการชนกันของแผ่นธรณี เป็นหลักฐานสำคัญของการปิดตัวของมหาสมุทรในอดีต",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/2 อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี"}},{number:18,type:"question",question:"ข้อใดคือความแตกต่างระหว่างรอยต่อแบบแยกตัวบนทวีป (Continental Rift) และสันเขากลางสมุทร (Mid-ocean Ridge)",options:["ไม่มีความแตกต่างกัน ทั้งสองเป็นกระบวนการแยกตัว เหมือนกัน","Continental Rift เกิดบนทวีป ส่วน Mid-ocean Ridge เกิดในมหาสมุทร","Continental Rift สร้างหินแกรนิต ส่วน Mid-ocean Ridge สร้างหินบะซอลต์","Continental Rift ไม่ทำให้เกิดแผ่นดินไหว แต่ Mid-ocean Ridge เกิดแผ่นดินไหว"],answer:"Continental Rift เกิดบนทวีป ส่วน Mid-ocean Ridge เกิดในมหาสมุทร",explanation:"ทั้งสองเป็นรอยต่อแบบแยกตัวเหมือนกัน แต่ Continental Rift เช่น หุบเขาทรุดแอฟริกาตะวันออก เป็นระยะเริ่มต้นของการแยกตัวที่เกิดขึ้นบนแผ่นทวีป ในขณะที่ Mid-ocean Ridge เป็นระยะที่เจริญเต็มที่แล้วและเกิดขึ้นในแอ่งมหาสมุทร",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:19,type:"question",question:"การที่แผ่นธรณีเคลื่อนที่ได้ เป็นเพราะคุณสมบัติของชั้นใด",options:["ธรณีภาค (Lithosphere) ที่เป็นของแข็ง","ฐานธรณีภาค (Asthenosphere) ที่มีสภาพพลาสติก","มัชฌิมภาค (Mesosphere) ที่เป็นของแข็ง","แก่นโลกชั้นนอก (Outer Core) ที่เป็นของเหลว"],answer:"ฐานธรณีภาค (Asthenosphere) ที่มีสภาพพลาสติก",explanation:"ฐานธรณีภาค (Asthenosphere) มีคุณสมบัติเป็นของแข็งเนื้ออ่อนคล้ายพลาสติก ทำให้แผ่นธรณีภาค (Lithosphere) ที่แข็งเกร็งกว่าสามารถ 'ลอย' และเคลื่อนที่ไปบนชั้นนี้ได้",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:20,type:"question",question:"เทือกเขาแอปพาเลเชียนในอเมริกาเหนือ เทือกเขาแอตลาสในแอฟริกา และเทือกเขาแอลป์ในยุโรป มีความเกี่ยวข้องกับการแปรสัณฐานอย่างไร",options:["เกิดจากการแยกตัวของแผ่นธรณีในยุคปัจจุบัน","เกิดจากจุดร้อนที่เรียงตัวกันเป็นแนวยาวใต้เปลือกโลก","เป็นแนวเทือกเขาที่เกิดจากการปิดตัวของมหาสมุทรและการชนกันของทวีปในอดีต","เป็นแนวภูเขาไฟที่ยังคุกรุ่นอยู่และมีการปะทุต่อเนื่อง"],answer:"เป็นแนวเทือกเขาที่เกิดจากการปิดตัวของมหาสมุทรและการชนกันของทวีปในอดีต",explanation:"เทือกเขาเหล่านี้เป็นตัวอย่างของเทือกเขาที่เกิดจากการชนกันของแผ่นธรณีในอดีต ซึ่งเป็นส่วนหนึ่งของวัฏจักรวิลสันที่มหาสมุทรโบราณปิดตัวลงและทวีปต่างๆ เคลื่อนที่เข้ามารวมกันเป็นมหาทวีปพันเจีย",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/2 อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี"}},{number:21,type:"question",question:"ข้อใดคือตัวอย่างของรอยต่อแผ่นธรณีแบบเคลื่อนเข้าหากันระหว่างแผ่นธรณีมหาสมุทรสองแผ่น",options:["เทือกเขาหิมาลัยและที่ราบสูงทิเบต","ร่องลึกก้นสมุทรมาเรียนาและหมู่เกาะมาเรียนา","สันเขากลางมหาสมุทรแอตแลนติกและเกาะไอซ์แลนด์","รอยเลื่อนซานแอนเดรียสในรัฐแคลิฟอร์เนีย"],answer:"ร่องลึกก้นสมุทรมาเรียนาและหมู่เกาะมาเรียนา",explanation:"บริเวณนี้เกิดจากการที่แผ่นธรณีแปซิฟิก (มหาสมุทร) มุดตัวลงใต้แผ่นธรณีมาเรียนา (มหาสมุทร) ทำให้เกิดร่องลึกก้นสมุทรที่ลึกที่สุดในโลก และแนวหมู่เกาะภูเขาไฟมาเรียนาขึ้นมา",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:22,type:"question",question:"การกระจายตัวของแผ่นดินไหวในบริเวณเขตมุดตัว (Subduction Zone) ที่เรียกว่า 'เขตเบนิออฟ' (Wadati-Benioff Zone) มีลักษณะอย่างไร",options:["เกิดแผ่นดินไหวระดับตื้นกระจายเป็นวงกว้าง","เกิดแผ่นดินไหวระดับลึกเท่านั้น","เกิดแผ่นดินไหวเรียงตัวเอียงลาดลงไปใต้แผ่นธรณีอีกแผ่น","เกิดแผ่นดินไหวในแนวตั้งฉากกับร่องลึกก้นสมุทร"],answer:"เกิดแผ่นดินไหวเรียงตัวเอียงลาดลงไปใต้แผ่นธรณีอีกแผ่น",explanation:"เขตเบนิออฟคือโซนของแผ่นดินไหวที่เกิดจากการเสียดสีและการแตกหักของแผ่นธรณีที่กำลังมุดตัวลงไป ทำให้จุดศูนย์เกิดแผ่นดินไหวมีตั้งแต่ระดับตื้นใกล้ร่องลึกก้นสมุทร ไปจนถึงระดับลึกใต้แผ่นธรณีอีกแผ่นหนึ่งเป็นแนวเอียง",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:23,type:"question",question:"ภูเขาใต้ทะเลที่มีลักษณะยอดตัดเรียบ (Guyot) เกิดขึ้นได้อย่างไร และบ่งบอกถึงอะไร",options:["เกิดจากภูเขาไฟที่ยังคุกรุ่นอยู่ใต้ทะเลและกำลังก่อตัวขึ้น","เกิดจากภูเขาไฟที่เคยเป็นเกาะแล้วถูกคลื่นกัดเซาะจนยอดเรียบก่อนจะจมตัวลง","เกิดจากการสะสมตัวของปะการังบนยอดภูเขาไฟที่จมอยู่ใต้น้ำ","เกิดจากการยกตัวของพื้นมหาสมุทรทำให้ยอดภูเขาไฟโผล่พ้นน้ำ"],answer:"เกิดจากภูเขาไฟที่เคยเป็นเกาะแล้วถูกคลื่นกัดเซาะจนยอดเรียบก่อนจะจมตัวลง",explanation:"Guyot คือภูเขาไฟใต้ทะเลที่เคยสูงพ้นระดับน้ำทะเล ทำให้ยอดของมันถูกคลื่นกัดเซาะจนเรียบ จากนั้นเมื่อแผ่นธรณีเคลื่อนที่ออกจากจุดร้อนและเย็นตัวลง มันก็จะจมตัวลงใต้ระดับน้ำทะเลอีกครั้ง เป็นหลักฐานสนับสนุนการเคลื่อนที่และการทรุดตัวของแผ่นธรณี",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/2 อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี"}},{number:24,type:"multiple-select",question:"ข้อใดคือแรงขับเคลื่อนหลักที่ทำให้แผ่นธรณีภาคเคลื่อนที่ (เลือกตอบได้มากกว่า 1 ข้อ)",options:["แรงดึงจากการมุดตัว (Slab Pull)","แรงผลักจากสันเขา (Ridge Push)","การพาความร้อนในชั้นเนื้อโลก (Mantle Convection)","แรงดึงดูดจากดวงจันทร์ (Tidal Force)"],answer:["แรงดึงจากการมุดตัว (Slab Pull)","แรงผลักจากสันเขา (Ridge Push)","การพาความร้อนในชั้นเนื้อโลก (Mantle Convection)"],explanation:"ปัจจุบันเชื่อว่าการเคลื่อนที่ของแผ่นธรณีเกิดจากแรงหลายอย่างทำงานร่วมกัน โดยมี Slab Pull เป็นแรงที่สำคัญที่สุด ตามมาด้วย Ridge Push และการไหลเวียนของกระแสการพาความร้อนในชั้นเนื้อโลก ส่วนแรงจากดวงจันทร์มีผลน้อยมาก",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}},{number:25,type:"question",question:"การค้นพบปล่องความร้อนใต้ทะเล (Hydrothermal Vents) ที่สันเขากลางสมุทร มีความสำคัญอย่างไร",options:["เป็นหลักฐานว่าใต้ทะเลลึกมีสิ่งมีชีวิตอาศัยอยู่ได้โดยไม่ต้องใช้แสง","เป็นหลักฐานสนับสนุนว่ามีการไหลเวียนของน้ำและความร้อนที่รอยต่อแบบแยกตัว","เป็นแหล่งพลังงานความร้อนใต้พิภพใหม่สำหรับมนุษย์ในอนาคต","เป็นสาเหตุหลักของการเกิดคลื่นสึนามิขนาดใหญ่ในมหาสมุทร"],answer:"เป็นหลักฐานสนับสนุนว่ามีการไหลเวียนของน้ำและความร้อนที่รอยต่อแบบแยกตัว",explanation:"การพบปล่องที่พ่นน้ำร้อนและแร่ธาตุออกมา เป็นการยืนยันว่ามีแหล่งความร้อน (แมกมา) อยู่ตื้นใต้สันเขากลางสมุทร และมีน้ำทะเลไหลเวียนลงไปรับความร้อนแล้วพุ่งกลับขึ้นมา ซึ่งสนับสนุนทฤษฎีการแผ่ขยายพื้นสมุทรอย่างยิ่ง",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/2 อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี"}},{number:26,type:"question",question:"ตามวัฏจักรวิลสัน (Wilson Cycle) ทะเลแดง (Red Sea) จัดอยู่ในระยะใด",options:["ระยะเริ่มต้นการแยกตัวของทวีป (Embryonic Stage)","ระยะเยาว์วัยที่เกิดเป็นแอ่งมหาสมุทรแคบๆ (Juvenile Stage)","ระยะเจริญเต็มที่ (Mature Stage) เช่น มหาสมุทรแอตแลนติก","ระยะปิดตัว (Closing Stage) เช่น ทะเลเมดิเตอร์เรเนียน"],answer:"ระยะเยาว์วัยที่เกิดเป็นแอ่งมหาสมุทรแคบๆ (Juvenile Stage)",explanation:"ทะเลแดงเป็นตัวอย่างของแอ่งมหาสมุทรที่เพิ่งเริ่มต้นก่อตัวขึ้นจากการที่แผ่นธรณีอาหรับแยกตัวออกจากแผ่นแอฟริกา ซึ่งเป็นระยะที่สองของวัฏจักรวิลสัน",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/2 อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี"}},{number:27,type:"question",question:"เทือกเขาอูราล (Ural Mountains) ที่แบ่งทวีปยุโรปและเอเชีย เป็นหลักฐานทางธรณีวิทยาของเหตุการณ์ใดในอดีต",options:["การเกิดจุดร้อนขนาดใหญ่","การแยกตัวของทวีป","การชนกันของแผ่นธรณีทวีปในอดีต","การเกิดรอยเลื่อนตามแนวระดับ"],answer:"การชนกันของแผ่นธรณีทวีปในอดีต",explanation:"เทือกเขาอูราลเป็นแนวเทือกเขาโบราณที่เกิดจากการชนกันของแผ่นทวีปไซบีเรียและแผ่นทวีปยุโรปเมื่อหลายร้อยล้านปีก่อน ซึ่งเป็นส่วนหนึ่งของการรวมตัวเป็นมหาทวีปพันเจีย",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/2 อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี"}},{number:28,type:"fill-in-number",question:"ถ้าสันเขากลางสมุทรแห่งหนึ่งมีอัตราการแผ่ขยายครึ่งซีก (half-spreading rate) 1.5 เซนติเมตรต่อปี หินที่อยู่ห่างจากสันเขา 60 กิโลเมตร จะมีอายุประมาณกี่ล้านปี",answer:4,unit:"ล้านปี",hint:"อายุ = ระยะทาง / อัตราเร็ว อย่าลืมแปลงหน่วยให้ตรงกัน",explanation:"ระยะทาง = 60 km = 6,000,000 cm. เวลา = ระยะทาง / อัตราเร็ว = 6,000,000 cm / 1.5 cm/ปี = 4,000,000 ปี หรือ 4 ล้านปี",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/2 อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี"}},{number:29,type:"question",question:"ข้อใดคือความหมายของ 'เทอร์เรน' (Terrane) ในบริบทของธรณีแปรสัณฐาน",options:["พื้นที่ที่มีลักษณะภูมิประเทศและโครงสร้างทางธรณีวิทยาแบบเดียวกัน","เศษเสี้ยวของแผ่นธรณีภาคที่เคลื่อนที่มาแปะติดกับทวีปอื่น","บริเวณที่เกิดแผ่นดินไหวบ่อยครั้งและมีความเสี่ยงสูง","ชั้นหินที่เกิดจากการสะสมตัวของตะกอนภูเขาไฟในทะเล"],answer:"เศษเสี้ยวของแผ่นธรณีภาคที่เคลื่อนที่มาแปะติดกับทวีปอื่น",explanation:"เทอร์เรน คือกลุ่มหินหรือเศษเสี้ยวของเปลือกโลกที่มีประวัติทางธรณีวิทยาแตกต่างจากบริเวณโดยรอบ และเชื่อว่ามันได้เคลื่อนที่มากับแผ่นธรณีแล้วมาชนและแปะติด (accrete) เข้ากับขอบของทวีปอื่น",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/2 อธิบายหลักฐานทางธรณีวิทยาที่สนับสนุนการเคลื่อนที่ของแผ่นธรณี"}},{number:30,type:"question",question:"การที่โลกมีกิจกรรมทางธรณีแปรสัณฐานที่คุกรุ่นอยู่ มีความสำคัญต่อวัฏจักรคาร์บอนและภูมิอากาศของโลกอย่างไร",options:["ไม่มีความเกี่ยวข้องกันเลยเนื่องจากเป็นคนละระบบกัน","ทำให้เกิดการปล่อยคาร์บอนไดออกไซด์จากภูเขาไฟ ซึ่งช่วยควบคุมอุณหภูมิโลกในระยะยาว","ทำให้เกิดการดูดซับคาร์บอนไดออกไซด์ทั้งหมดลงไปเก็บในชั้นเนื้อโลก","ทำให้แกนโลกเอียงและเกิดฤดูกาลที่แตกต่างกันในแต่ละพื้นที่"],answer:"ทำให้เกิดการปล่อยคาร์บอนไดออกไซด์จากภูเขาไฟ ซึ่งช่วยควบคุมอุณหภูมิโลกในระยะยาว",explanation:"ภูเขาไฟที่เกิดจากการแปรสัณฐานของแผ่นธรณีจะปล่อยแก๊สคาร์บอนไดออกไซด์ออกมา ซึ่งเป็นแก๊สเรือนกระจกที่ช่วยให้โลกอบอุ่น กระบวนการนี้เป็นส่วนหนึ่งของวัฏจักรคาร์บอนทางธรณีวิทยาที่ช่วยรักษาเสถียรภาพของภูมิอากาศโลกในระยะเวลาหลายล้านปี",subCategory:{main:"การแปรสัณฐานของแผ่นธรณี",specific:"ว 3.2 ม.6/3 ระบุสาเหตุ และอธิบายรูปแบบแนวรอยต่อของแผ่นธรณีที่สัมพันธ์กับการเคลื่อนที่"}}];export{e as quizItems};
